INSERT INTO `appendix_equations` (`appendix_equation_id`, `appendix_module_id`, `appendix_section_id`, `repo_object_id`, `appendix_equation_number`, `source_equation_number`, `title`, `equation_latex`, `word_latex`, `equation_role`, `status`, `created_revision_id`) VALUES
(1, 1, 2, 49, 'M1.1', '3.7', 'Teilmengenbeziehung', 'A \\subseteq B \\Longleftrightarrow \\forall x\\,(x \\in A \\Rightarrow x \\in B)', 'A \\subseteq B \\Longleftrightarrow \\forall x\\,(x \\in A \\Rightarrow x \\in B)', 'derived', 'final', 6),
(2, 1, 2, 50, 'M1.2', '3.8', 'Echte Teilmenge', 'A \\subset B \\Longleftrightarrow A \\subseteq B \\land A \\neq B', 'A \\subset B \\Longleftrightarrow A \\subseteq B \\land A \\neq B', 'derived', 'final', 6),
(3, 1, 2, 51, 'M1.3', '3.9', 'Extensional bestimmte Mengengleichheit', 'A = B \\Longleftrightarrow \\forall x\\,(x \\in A \\Leftrightarrow x \\in B)', 'A = B \\Longleftrightarrow \\forall x\\,(x \\in A \\Leftrightarrow x \\in B)', 'derived', 'final', 6),
(4, 1, 3, 52, 'M1.4', '3.10', 'Charakterisierung der leeren Menge', '\\varnothing = \\{x\\mid x \\neq x\\}', '\\varnothing = \\{x\\mid x \\neq x\\}', 'derived', 'final', 6),
(5, 1, 3, 53, 'M1.5', '3.11', 'Leere Menge als Teilmenge jeder Menge', '\\varnothing \\subseteq A', '\\varnothing \\subseteq A', 'derived', 'final', 6),
(6, 1, 3, 54, 'M1.6', '3.12', 'Vereinigung', 'A \\cup B = \\{x\\mid x \\in A \\vee x \\in B\\}', 'A \\cup B = \\{x\\mid x \\in A \\vee x \\in B\\}', 'derived', 'final', 6),
(7, 1, 3, 55, 'M1.7', '3.13', 'Schnittmenge', 'A \\cap B = \\{x\\mid x \\in A \\land x \\in B\\}', 'A \\cap B = \\{x\\mid x \\in A \\land x \\in B\\}', 'derived', 'final', 6),
(8, 1, 3, 56, 'M1.8', '3.14', 'Mengendifferenz', 'A \\setminus B = \\{x\\mid x \\in A \\land x \\notin B\\}', 'A \\setminus B = \\{x\\mid x \\in A \\land x \\notin B\\}', 'derived', 'final', 6),
(9, 1, 3, 57, 'M1.9', '3.15', 'Disjunktheit', 'A \\cap B = \\varnothing', 'A \\cap B = \\varnothing', 'derived', 'final', 6),
(10, 1, 4, 58, 'M1.10', '3.16', 'Potenzmenge', '\\mathcal{P}(A) = \\{B\\mid B \\subseteq A\\}', '\\mathcal{P}(A) = \\{B\\mid B \\subseteq A\\}', 'derived', 'final', 6),
(11, 1, 4, 59, 'M1.11', '3.17', 'Potenzmenge einer zweielementigen Menge', '\\mathcal{P}(A) = \\{\\varnothing,\\{a\\},\\{b\\},\\{a,b\\}\\}', '\\mathcal{P}(A) = \\{\\varnothing,\\{a\\},\\{b\\},\\{a,b\\}\\}', 'derived', 'final', 6),
(12, 1, 4, 60, 'M1.12', '3.18', 'Mächtigkeit der Potenzmenge einer endlichen Menge', '|A| = n \\Rightarrow |\\mathcal{P}(A)| = 2^{n}', '|A| = n \\Rightarrow |\\mathcal{P}(A)| = 2^{n}', 'derived', 'final', 6),
(13, 1, 5, 61, 'M1.13', '3.19', 'Reihenfolge im geordneten Paar', '(a,b) \\neq (b,a)\\qquad\\text{für }a \\neq b', '(a,b) \\neq (b,a)\\quad\\text{für }a \\neq b', 'derived', 'final', 6),
(14, 1, 5, 62, 'M1.14', '3.20', 'Kartesisches Produkt', 'A \\times B = \\{(a,b)\\mid a \\in A \\land b \\in B\\}', 'A \\times B = \\{(a,b)\\mid a \\in A \\land b \\in B\\}', 'derived', 'final', 6),
(15, 1, 5, 63, 'M1.15', '3.21', 'Mächtigkeit eines endlichen kartesischen Produkts', '|A \\times B| = |A|\\cdot|B|', '|A \\times B| = |A|\\cdot|B|', 'derived', 'final', 6),
(16, 1, 6, 68, 'M1.16', '3.26', 'Bild der Definitionsmenge', 'f(A) = \\{f(a)\\mid a \\in A\\} \\subseteq B', 'f(A) = \\{f(a)\\mid a \\in A\\} \\subseteq B', 'derived', 'final', 6),
(17, 1, 6, 69, 'M1.17', '3.27', 'Bild einer Teilmenge', 'f(C) = \\{f(c)\\mid c \\in C\\}', 'f(C) = \\{f(c)\\mid c \\in C\\}', 'derived', 'final', 6),
(18, 1, 6, 70, 'M1.18', '3.28', 'Urbild einer Teilmenge', 'f^{-1}(D) = \\{a \\in A\\mid f(a) \\in D\\}', 'f^{-1}(D) = \\{a \\in A\\mid f(a) \\in D\\}', 'derived', 'final', 6),
(19, 1, 7, 75, 'M1.19', '3.33', 'Identische Funktion', 'id_{A}:A \\rightarrow A,\\qquad id_{A}(a) = a\\quad\\forall a \\in A', 'id_{A}:A \\rightarrow A,\\quad id_{A}(a) = a\\quad\\forall a \\in A', 'derived', 'final', 6),
(20, 1, 7, 76, 'M1.20', '3.34', 'Verkettung zweier Funktionen', 'g \\circ f:A \\rightarrow C,\\qquad (g \\circ f)(a) = g\\bigl(f(a)\\bigr)', 'g \\circ f:A \\rightarrow C,\\quad (g \\circ f)(a) = g(f(a))', 'derived', 'final', 6),
(21, 1, 7, 77, 'M1.21', '3.35', 'Nichtkommutativität im Allgemeinen', 'g \\circ f \\neq f \\circ g', 'g \\circ f \\neq f \\circ g', 'derived', 'final', 6),
(22, 1, 7, 78, 'M1.22', '3.36', 'Assoziativität der Funktionsverkettung', 'h \\circ (g \\circ f) = (h \\circ g) \\circ f', 'h \\circ (g \\circ f) = (h \\circ g) \\circ f', 'derived', 'final', 6),
(23, 1, 8, 79, 'M1.23', '3.37', 'Funktion mit zwei Eingangsgrößen', 'f:A \\times B \\rightarrow C,\\qquad f(a,b) = c \\in C,\\quad a \\in A,\\ b \\in B', 'f:A \\times B \\rightarrow C,\\quad f(a,b) = c \\in C,\\quad a \\in A,\\ b \\in B', 'derived', 'final', 6),
(24, 1, 8, 80, 'M1.24', '3.38', 'Funktion mit n Eingangsgrößen', '\\begin{aligned}\nf&:A_{1} \\times A_{2} \\times \\cdots \\times A_{n} \\rightarrow B,\\\\\n(a_{1},a_{2},\\ldots,a_{n})&\\in A_{1} \\times A_{2} \\times \\cdots \\times A_{n},\\\\\nf(a_{1},a_{2},\\ldots,a_{n})&\\in B.\n\\end{aligned}', '\\begin{matrix} f:A_{1} \\times A_{2} \\times \\cdots \\times A_{n} \\rightarrow B, \\\\ (a_{1},a_{2},\\ldots,a_{n}) \\in A_{1} \\times A_{2} \\times \\cdots \\times A_{n}, \\\\ f(a_{1},a_{2},\\ldots,a_{n}) \\in B \\end{matrix}', 'derived', 'final', 6),
(25, 1, 9, 81, 'M1.25', '3.39', 'Parametrisierte Funktionsfamilie', '\\{f_{\\theta}\\mid \\theta \\in \\Theta\\},\\qquad f_{\\theta}:A \\rightarrow B\\quad\\forall\\theta \\in \\Theta', '\\{f_{\\theta}\\mid \\theta \\in \\Theta\\},\\quad f_{\\theta}:A \\rightarrow B\\quad\\forall\\theta \\in \\Theta', 'derived', 'final', 6),
(26, 1, 9, 82, 'M1.26', '3.40', 'Partielle Funktion', 'f:D \\rightarrow B,\\qquad D \\subseteq A', 'f:D \\rightarrow B,\\quad D \\subseteq A', 'derived', 'final', 6),
(50, 2, 12, 95, 'M2.1', '3.53', 'Abgeschlossenheit der Vektoraddition', 'x+yin V', 'x+yin V', 'derived', 'final', 7),
