(53, 2, 13, 98, 'M2.4', '3.56', 'Nullvektor und neutrale Wirkung', '0_{V}in V,quad x+0_{V}=0_{V}+x=xquadforall xin V', '0_{V}in V,quad x+0_{V}=0_{V}+x=xquadforall xin V', 'derived', 'final', 7),
(54, 2, 13, 99, 'M2.5', '3.57', 'Nullvektor im zweidimensionalen reellen Koordinatenraum', '0_{mathbb{R}^{2}}=egin{pmatrix}0\\0end{pmatrix}', '0_{mathbb{R}^{2}}=egin{pmatrix}0\\0end{pmatrix}', 'example', 'final', 7),
