(56, 2, 13, 101, 'M2.7', '3.59', 'Differenz als Addition des additiven Inversen', 'x-ycoloneqq x+(-y)', 'x-ycoloneqq x+(-y)', 'derived', 'final', 7),
(57, 2, 14, 102, 'M2.8', '3.60', 'Abgeschlossenheit der Skalarmultiplikation', 'lambda xin V', 'lambda xin V', 'derived', 'final', 7),
