(61, 2, 14, 106, 'M2.12', '3.64', 'Distributivität bezüglich der Skalaraddition', '(lambda+mu)x=lambda x+mu x', '(lambda+mu)x=lambda x+mu x', 'derived', 'final', 7),
(62, 2, 15, 107, 'M2.13', '3.65', 'Multiplikation eines Vektors mit dem skalaren Nullelement', '0_{K}x=0_{V}quadforall xin V', '0_{K}x=0_{V}quadforall xin V', 'derived', 'final', 7),
