(64, 2, 16, 109, 'M2.15', '3.67', 'Untervektorraumkriterium', 'egin{matrix}x,yin URightarrow x+yin U,\\ lambdain K, xin URightarrow lambda xin U.end{matrix}', 'egin{matrix}x,yin URightarrow x+yin U,\\ lambdain K, xin URightarrow lambda xin U.end{matrix}', 'derived', 'final', 7),
(65, 2, 17, 110, 'M2.16', '3.68', 'Reeller Koordinatenraum', 'mathbb{R}^{n}=left{egin{pmatrix}x_{1}\\vdots\\x_{n}end{pmatrix}middle|x_{1},ldots,x_{n}inmathbb{R}\right}', 'mathbb{R}^{n}=left{egin{pmatrix}x_{1}\\vdots\\x_{n}end{pmatrix}middle|x_{1},ldots,x_{n}inmathbb{R}\right}', 'example', 'final', 7),
