(67, 2, 18, 116, 'M2.18', '3.74', 'Kriterium linearer Abhängigkeit', 'exists,lambda_{1},ldots,lambda_{n}in K:quadleft(sum_{i=1}^{n}lambda_{i}v_{i}=0_{V}\right)landleft(exists j:lambda_{j}\neq0_{K}\right)', 'exists,lambda_{1},ldots,lambda_{n}in K:quadleft(sum_{i=1}^{n}lambda_{i}v_{i}=0_{V}\right)landleft(exists j:lambda_{j}\neq0_{K}\right)', 'derived', 'final', 7),
(68, 2, 18, 117, 'M2.19', '3.75', 'Darstellung eines redundanten Vektors durch die übrigen Vektoren', 'v_{j}=-frac{1}{lambda_{j}}sum_{substack{i=1\\i\neq j}}^{n}lambda_{i}v_{i}', 'v_{j}=-frac{1}{lambda_{j}}sum_{substack{i=1\\i\neq j}}^{n}lambda_{i}v_{i}', 'derived', 'final', 7),
(69, 2, 19, 118, 'M2.20', '3.76', 'Beispiel linearer Abhängigkeit', 'v_{2}=2v_{1}quadLongleftrightarrowquad2v_{1}-v_{2}=0_{mathbb{R}^{2}}', 'v_{2}=2v_{1}quadLongleftrightarrowquad2v_{1}-v_{2}=0_{mathbb{R}^{2}}', 'example', 'final', 7),
(70, 2, 19, 119, 'M2.21', '3.77', 'Beispiel linearer Unabhängigkeit', 'lambda_{1}egin{pmatrix}1\\0end{pmatrix}+lambda_{2}egin{pmatrix}0\\1end{pmatrix}=egin{pmatrix}0\\0end{pmatrix}quadLongrightarrowquadlambda_{1}=lambda_{2}=0', 'lambda_{1}egin{pmatrix}1\\0end{pmatrix}+lambda_{2}egin{pmatrix}0\\1end{pmatrix}=egin{pmatrix}0\\0end{pmatrix}quadLongrightarrowquadlambda_{1}=lambda_{2}=0', 'example', 'final', 7),
(71, 2, 20, 122, 'M2.22', '3.80', 'Standardbasis des reellen Koordinatenraums', 'E_{n}=(e_{1},ldots,e_{n}),quad e_{i}=egin{pmatrix}0\\vdots\\1\\vdots\\0end{pmatrix}', 'E_{n}=(e_{1},ldots,e_{n}),quad e_{i}=egin{pmatrix}0\\vdots\\1\\vdots\\0end{pmatrix}', 'example', 'final', 7),
(72, 2, 20, 123, 'M2.23', '3.81', 'Darstellung eines Vektors bezüglich der Standardbasis', 'v=v_{1}e_{1}+cdots+v_{n}e_{n}=sum_{i=1}^{n}v_{i}e_{i}', 'v=v_{1}e_{1}+cdots+v_{n}e_{n}=sum_{i=1}^{n}v_{i}e_{i}', 'example', 'final', 7),
(73, 3, 26, 86, 'M3.1', '3.44', 'Verkettung zweier Operatoren', 'A,B:V \\rightarrow V,\\quad (B\\circ A)(x)=B(A(x))', 'A,B:V \\rightarrow V,\\quad (B\\circ A)(x)=B(A(x))', 'derived', 'final', 8),
(74, 3, 26, 87, 'M3.2', '3.45', 'Nichtkommutativität der Operatorverkettung im Allgemeinen', 'B\\circ A\\neq A\\circ B', 'B\\circ A\\neq A\\circ B', 'derived', 'final', 8),
(75, 3, 26, 88, 'M3.3', '3.46', 'Identitätsoperator', 'I:V\\rightarrow V,\\quad I(x)=x\\quad\\forall x\\in V', 'I:V\\rightarrow V,\\quad I(x)=x\\quad\\forall x\\in V', 'derived', 'final', 8),
(76, 3, 26, 89, 'M3.4', '3.47', 'Neutrale Wirkung des Identitätsoperators', 'I\\circ T=T\\circ I=T', 'I\\circ T=T\\circ I=T', 'derived', 'final', 8),
(77, 3, 27, 92, 'M3.5', '3.50', 'Eigenwertbeziehung', 'Ax=\\lambda x,\\quad x\\neq0', 'Ax=\\lambda x,\\quad x\\neq0', 'derived', 'final', 8),
(78, 3, 28, 132, 'M3.6', '3.91', 'Konstruktion der Basiswechselmatrix aus Basisvektoren', 'P_{C\\rightarrow B}=\\begin{pmatrix}\\left\\lbrack c_{1}\\right\\rbrack_{B}&\\left\\lbrack c_{2}\\right\\rbrack_{B}&\\cdots&\\left\\lbrack c_{n}\\right\\rbrack_{B}\\end{pmatrix}', 'P_{C\\rightarrow B}=\\begin{pmatrix}\\left\\lbrack c_{1}\\right\\rbrack_{B}&\\left\\lbrack c_{2}\\right\\rbrack_{B}&\\cdots&\\left\\lbrack c_{n}\\right\\rbrack_{B}\\end{pmatrix}', 'proof_step', 'final', 8),
