(101, 4, 37, 155, 'M4.1', '3.114', 'Rang als Dimension von Spalten- und Zeilenraum', '\\text{rang}(A) = \\dim\\left( \\text{Spaltenraum}(A) \\right) = \\dim\\left( \\text{Zeilenraum}(A) \\right)', '\\text{rang}(A) = \\dim\\left( \\text{Spaltenraum}(A) \\right) = \\dim\\left( \\text{Zeilenraum}(A) \\right)', 'derived', 'final', 9),
(102, 4, 37, 156, 'M4.2', '3.115', 'Rang des Beispieloperators', '\\text{rang}(A) = 1', '\\text{rang}(A) = 1', 'example', 'final', 9),
(103, 4, 38, 160, 'M4.3', '3.119', 'Rang-Nullität im Beispiel', '2 = \\dim\\left( \\ker(A) \\right) + 1\\quad \\Longrightarrow \\quad\\dim\\left( \\ker(A) \\right) = 1', '2 = \\dim\\left( \\ker(A) \\right) + 1\\quad \\Longrightarrow \\quad\\dim\\left( \\ker(A) \\right) = 1', 'example', 'final', 9),
(104, 4, 39, 163, 'M4.4', '3.122', 'Lösbarkeit über die Bildzugehörigkeit', 'Ax = b\\,\\text{ist lösbar}\\quad \\Longleftrightarrow \\quad b \\in \\text{Bild}(A)', 'Ax = b\\,\\text{ist lösbar}\\quad \\Longleftrightarrow \\quad b \\in \\text{Bild}(A)', 'derived', 'final', 9),
(105, 4, 40, 164, 'M4.5', '3.123', 'Rangkriterium der erweiterten Matrix', 'Ax = b\\,\\text{ist lösbar}\\quad \\Longleftrightarrow \\quad\\text{rang}(A) = \\text{rang}\\left( A \\middle| b \\right)', 'Ax = b\\,\\text{ist lösbar}\\quad \\Longleftrightarrow \\quad\\text{rang}(A) = \\text{rang}\\left( A \\middle| b \\right)', 'derived', 'final', 9),
(106, 4, 41, 165, 'M4.6', '3.124', 'Vollständige Lösungsmenge aus spezieller Lösung und Kern', 'x = x_{0} + z,\\quad\\quad z \\in \\ker(A)', 'x = x_{0} + z,\\quad\\quad z \\in \\ker(A)', 'derived', 'final', 9),
(107, 5, 46, 173, 'M5.1', '3.132', 'Charakteristisches Polynom einer Diagonalmatrix', 'p_{A}(\\lambda)=\\det\\begin{pmatrix}2-\\lambda&0\\\\0&3-\\lambda\\end{pmatrix}=(2-\\lambda)(3-\\lambda)', 'p_{A}(\\lambda)=\\det\\begin{pmatrix}2-\\lambda&0\\\\0&3-\\lambda\\end{pmatrix}=(2-\\lambda)(3-\\lambda)', 'example', 'final', 10),
(108, 5, 46, 174, 'M5.2', '3.133', 'Eigenwerte der Diagonalmatrix', '\\lambda_{1}=2,\\quad\\lambda_{2}=3', '\\lambda_{1}=2,\\quad\\lambda_{2}=3', 'example', 'final', 10),
