(112, 5, 47, 180, 'M5.6', '3.139', 'Eindimensionaler Eigenraum zum doppelten Eigenwert', 'E_{2}=\\text{span}\\left\\{\\begin{pmatrix}1\\\\0\\end{pmatrix}\\right\\}', 'E_{2}=\\text{span}\\left\\{\\begin{pmatrix}1\\\\0\\end{pmatrix}\\right\\}', 'example', 'final', 10),
(113, 5, 48, 181, 'M5.7', '3.140', 'Determinante als Produkt der Eigenwerte', '\\det(A)=\\prod_{i=1}^{n}\\lambda_{i}', '\\det(A)=\\prod_{i=1}^{n}\\lambda_{i}', 'proof_step', 'final', 10),
