(116, 5, 49, 195, 'M5.10', '3.154', 'Diagonalisierbarkeit über die Summe der Eigenraumdimensionen', 'A\\,\\text{diagonalisierbar}\\quad\\Longleftrightarrow\\quad\\sum_{\\lambda\\in\\sigma(A)}\\dim\\left(E_{\\lambda}\\right)=n', 'A\\,\\text{diagonalisierbar}\\quad\\Longleftrightarrow\\quad\\sum_{\\lambda\\in\\sigma(A)}\\dim\\left(E_{\\lambda}\\right)=n', 'proof_step', 'final', 10),
