(120, 5, 50, 199, 'M5.14', '3.158', 'Eigenvektormatrix und Diagonalmatrix', 'P=\\begin{pmatrix}1&1\\\\1&-2\\end{pmatrix},\\quad D=\\begin{pmatrix}5&0\\\\0&2\\end{pmatrix}', 'P=\\begin{pmatrix}1&1\\\\1&-2\\end{pmatrix},\\quad D=\\begin{pmatrix}5&0\\\\0&2\\end{pmatrix}', 'example', 'final', 10),
(121, 5, 50, 200, 'M5.15', '3.159', 'Diagonalisierung durch Ähnlichkeitstransformation', 'P^{-1}AP=D', 'P^{-1}AP=D', 'example', 'final', 10),
(122, 5, 51, 201, 'M5.16', '3.160', 'Nichtdiagonalisierbarkeit', 'A\\,\\text{ist nicht diagonalisierbar}', 'A\\,\\text{ist nicht diagonalisierbar}', 'derived', 'final', 10),
(123, 5, 52, 202, 'M5.17', '3.161', 'Potenzen einer diagonalisierbaren Matrix', 'A^{k}=PD^{k}P^{-1}', 'A^{k}=PD^{k}P^{-1}', 'proof_step', 'final', 10),
(124, 5, 52, 203, 'M5.18', '3.162', 'Potenz einer Diagonalmatrix', 'D^{k}=\\begin{pmatrix}\\lambda_{1}^{k}&0&\\cdots&0\\\\0&\\lambda_{2}^{k}&\\cdots&0\\\\\\vdots&\\vdots&\\ddots&\\vdots\\\\0&0&\\cdots&\\lambda_{n}^{k}\\end{pmatrix}', 'D^{k}=\\begin{pmatrix}\\lambda_{1}^{k}&0&\\cdots&0\\\\0&\\lambda_{2}^{k}&\\cdots&0\\\\\\vdots&\\vdots&\\ddots&\\vdots\\\\0&0&\\cdots&\\lambda_{n}^{k}\\end{pmatrix}', 'proof_step', 'final', 10),
(125, 5, 52, 204, 'M5.19', '3.163', 'Matrixfunktion über die Diagonalisierung', 'f(A)=P\\,f(D)\\,P^{-1}', 'f(A)=P\\,f(D)\\,P^{-1}', 'proof_step', 'final', 10),
(126, 5, 52, 205, 'M5.20', '3.164', 'Funktion einer Diagonalmatrix', 'f(D)=\\begin{pmatrix}f(\\lambda_{1})&0&\\cdots&0\\\\0&f(\\lambda_{2})&\\cdots&0\\\\\\vdots&\\vdots&\\ddots&\\vdots\\\\0&0&\\cdots&f(\\lambda_{n})\\end{pmatrix}', 'f(D)=\\begin{pmatrix}f(\\lambda_{1})&0&\\cdots&0\\\\0&f(\\lambda_{2})&\\cdots&0\\\\\\vdots&\\vdots&\\ddots&\\vdots\\\\0&0&\\cdots&f(\\lambda_{n})\\end{pmatrix}', 'proof_step', 'final', 10),
(127, 5, 53, 210, 'M5.21', '3.169', 'Spektralzerlegung bezüglich einer orthonormalen Eigenbasis', 'A=\\sum_{i=1}^{n}\\lambda_{i}q_{i}q_{i}^{T}', 'A=\\sum_{i=1}^{n}\\lambda_{i}q_{i}q_{i}^{T}', 'proof_step', 'final', 10),
(128, 5, 53, 211, 'M5.22', '3.170', 'Spektralzerlegung über Eigenraumprojektoren', 'A=\\sum_{\\lambda\\in\\sigma(A)}\\lambda P_{\\lambda}', 'A=\\sum_{\\lambda\\in\\sigma(A)}\\lambda P_{\\lambda}', 'proof_step', 'final', 10),
(129, 5, 53, 212, 'M5.23', '3.171', 'Vollständigkeitsrelation der Rang-eins-Projektoren', '\\sum_{i=1}^{n}q_{i}q_{i}^{T}=I', '\\sum_{i=1}^{n}q_{i}q_{i}^{T}=I', 'proof_step', 'final', 10),
(130, 5, 53, 213, 'M5.24', '3.172', 'Vollständigkeitsrelation der Eigenraumprojektoren', '\\sum_{\\lambda\\in\\sigma(A)}P_{\\lambda}=I', '\\sum_{\\lambda\\in\\sigma(A)}P_{\\lambda}=I', 'proof_step', 'final', 10),
(131, 5, 53, 214, 'M5.25', '3.173', 'Orthogonalität verschiedener Eigenprojektoren', 'P_{\\lambda}P_{\\mu}=0\\quad\\text{für }\\lambda\\neq\\mu', 'P_{\\lambda}P_{\\mu}=0\\quad\\text{für }\\lambda\\neq\\mu', 'proof_step', 'final', 10),
(132, 5, 53, 215, 'M5.26', '3.174', 'Idempotenz eines Eigenprojektors', 'P_{\\lambda}^{2}=P_{\\lambda}', 'P_{\\lambda}^{2}=P_{\\lambda}', 'proof_step', 'final', 10),
(133, 5, 54, 216, 'M5.27', '3.175', 'Zerlegung eines beliebigen Vektors in Eigenrichtungen', 'x=\\sum_{i=1}^{n}\\left(q_{i}^{T}x\\right)\\,q_{i}', 'x=\\sum_{i=1}^{n}\\left(q_{i}^{T}x\\right)\\,q_{i}', 'proof_step', 'final', 10),
(134, 5, 54, 217, 'M5.28', '3.176', 'Operatorwirkung auf die Eigenkomponenten eines Vektors', 'Ax=\\sum_{i=1}^{n}\\lambda_{i}\\left(q_{i}^{T}x\\right)\\,q_{i}', 'Ax=\\sum_{i=1}^{n}\\lambda_{i}\\left(q_{i}^{T}x\\right)\\,q_{i}', 'proof_step', 'final', 10),
(135, 5, 55, 218, 'M5.29', '3.177', 'Matrixfunktion bezüglich einer orthonormalen Eigenbasis', 'f(A)=\\sum_{i=1}^{n}f(\\lambda_{i})\\,q_{i}q_{i}^{T}', 'f(A)=\\sum_{i=1}^{n}f(\\lambda_{i})\\,q_{i}q_{i}^{T}', 'proof_step', 'final', 10),
(136, 5, 55, 219, 'M5.30', '3.178', 'Matrixfunktion über Eigenraumprojektoren', 'f(A)=\\sum_{\\lambda\\in\\sigma(A)}f(\\lambda)P_{\\lambda}', 'f(A)=\\sum_{\\lambda\\in\\sigma(A)}f(\\lambda)P_{\\lambda}', 'proof_step', 'final', 10),
(137, 6, 59, 231, 'M6.1', '3.190', 'Abstand zweier Vektoren', 'd(x,y)=\\lVert x-y\\rVert', 'd(x,y)=\\lVert x-y\\rVert', 'canonical', 'final', 11),
(138, 6, 59, 232, 'M6.2', '3.191', 'Struktureller Übergang vom Skalarprodukt zum Abstand', '\\text{Skalarprodukt}\\longrightarrow\\text{Norm}\\longrightarrow\\text{Abstand}', '\\text{Skalarprodukt}\\longrightarrow\\text{Norm}\\longrightarrow\\text{Abstand}', 'canonical', 'final', 11),
(139, 6, 60, 233, 'M6.3', '3.192', 'Cauchy-Schwarz-Ungleichung', '\\left|\\langle x,y\\rangle\\right|\\leq\\lVert x\\rVert\\,\\lVert y\\rVert', '\\left|\\langle x,y\\rangle\\right|\\leq\\lVert x\\rVert\\,\\lVert y\\rVert', 'proof_step', 'final', 11),
(140, 6, 60, 234, 'M6.4', '3.193', 'Normierter Skalarproduktquotient', '-1\\leq\\frac{\\langle x,y\\rangle}{\\lVert x\\rVert\\,\\lVert y\\rVert}\\leq1', '-1\\leq\\frac{\\langle x,y\\rangle}{\\lVert x\\rVert\\,\\lVert y\\rVert}\\leq1', 'proof_step', 'final', 11),
(141, 6, 60, 235, 'M6.5', '3.194', 'Winkeldefinition', '\\cos\\theta=\\frac{\\langle x,y\\rangle}{\\lVert x\\rVert\\,\\lVert y\\rVert}', '\\cos\\theta=\\frac{\\langle x,y\\rangle}{\\lVert x\\rVert\\,\\lVert y\\rVert}', 'canonical', 'final', 11),
(142, 6, 60, 236, 'M6.6', '3.195', 'Winkelbeziehung für normierte Vektoren', '\\cos\\theta=\\langle x,y\\rangle', '\\cos\\theta=\\langle x,y\\rangle', 'canonical', 'final', 11),
(143, 6, 61, 238, 'M6.7', '3.197', 'Satz des Pythagoras für orthogonale Vektoren', '\\lVert x+y\\rVert^{2}=\\lVert x\\rVert^{2}+\\lVert y\\rVert^{2}', '\\lVert x+y\\rVert^{2}=\\lVert x\\rVert^{2}+\\lVert y\\rVert^{2}', 'proof_step', 'final', 11),
(144, 6, 61, 239, 'M6.8', '3.198', 'Herleitung des Satzes des Pythagoras', '\\begin{matrix}\\lVert x+y\\rVert^{2}=\\langle x+y,x+y\\rangle\\\\=\\langle x,x\\rangle+2\\langle x,y\\rangle+\\langle y,y\\rangle\\\\=\\lVert x\\rVert^{2}+\\lVert y\\rVert^{2}.\\end{matrix}', '\\begin{matrix}\\lVert x+y\\rVert^{2}=\\langle x+y,x+y\\rangle\\\\=\\langle x,x\\rangle+2\\langle x,y\\rangle+\\langle y,y\\rangle\\\\=\\lVert x\\rVert^{2}+\\lVert y\\rVert^{2}.\\end{matrix}', 'proof_step', 'final', 11),
(145, 6, 62, 240, 'M6.9', '3.199', 'Bedingung eines normierten Vektors', '\\lVert x\\rVert=1', '\\lVert x\\rVert=1', 'canonical', 'final', 11),
(146, 6, 62, 241, 'M6.10', '3.200', 'Normierung eines von null verschiedenen Vektors', '\\widehat{x}=\\frac{x}{\\lVert x\\rVert}', '\\widehat{x}=\\frac{x}{\\lVert x\\rVert}', 'canonical', 'final', 11),
(147, 6, 63, 248, 'M6.11', '3.207', 'Orthogonales Komplement eines Unterraums', 'U^{\\perp}=\\left\\{x\\in V\\mid\\langle x,u\\rangle=0\\text{ für alle }u\\in U\\right\\}', 'U^{\\perp}=\\left\\{x\\in V\\mid\\langle x,u\\rangle=0\\text{ für alle }u\\in U\\right\\}', 'canonical', 'final', 11),
(148, 6, 63, 249, 'M6.12', '3.208', 'Direkte orthogonale Zerlegung des Raums', 'V=U\\oplus U^{\\perp}', 'V=U\\oplus U^{\\perp}', 'canonical', 'final', 11),
(149, 6, 63, 250, 'M6.13', '3.209', 'Zerlegung eines Vektors in Unterraum- und Orthogonalanteil', 'x=u+u_{\\perp},\\quad u\\in U,\\quad u_{\\perp}\\in U^{\\perp}', 'x=u+u_{\\perp},\\quad u\\in U,\\quad u_{\\perp}\\in U^{\\perp}', 'canonical', 'final', 11),
(150, 6, 64, 253, 'M6.14', '3.212', 'Orthogonale Projektion in einer orthonormalen Basis', 'P_{U}x=\\sum_{i=1}^{m}\\langle q_{i},x\\rangle q_{i}', 'P_{U}x=\\sum_{i=1}^{m}\\langle q_{i},x\\rangle q_{i}', 'proof_step', 'final', 11),
(151, 6, 64, 254, 'M6.15', '3.213', 'Projektormatrix aus einer orthonormalen Basismatrix', 'P_{U}=QQ^{T}', 'P_{U}=QQ^{T}', 'proof_step', 'final', 11),
(152, 6, 64, 255, 'M6.16', '3.214', 'Matrixform der Projektion eines Vektors', 'P_{U}x=QQ^{T}x', 'P_{U}x=QQ^{T}x', 'proof_step', 'final', 11),
(153, 6, 64, 256, 'M6.17', '3.215', 'Idempotenz des orthogonalen Projektors', 'P_{U}^{2}=P_{U}', 'P_{U}^{2}=P_{U}', 'proof_step', 'final', 11),
(154, 6, 64, 257, 'M6.18', '3.216', 'Symmetrie des orthogonalen Projektors', 'P_{U}^{T}=P_{U}', 'P_{U}^{T}=P_{U}', 'proof_step', 'final', 11),
(155, 6, 65, 258, 'M6.19', '3.217', 'Projektorzerlegung eines Vektors', 'x=P_{U}x+\\left(I-P_{U}\\right)x', 'x=P_{U}x+\\left(I-P_{U}\\right)x', 'proof_step', 'final', 11),
(156, 6, 65, 259, 'M6.20', '3.218', 'Orthogonalität von Projektions- und Restanteil', '\\left\\langle P_{U}x,\\left(I-P_{U}\\right)x\\right\\rangle=0', '\\left\\langle P_{U}x,\\left(I-P_{U}\\right)x\\right\\rangle=0', 'proof_step', 'final', 11),
(157, 6, 66, 260, 'M6.21', '3.219', 'Erster Gram-Schmidt-Schritt', 'u_{1}=v_{1}', 'u_{1}=v_{1}', 'proof_step', 'final', 11),
(158, 6, 66, 261, 'M6.22', '3.220', 'Zweiter Gram-Schmidt-Schritt', 'u_{2}=v_{2}-\\frac{\\langle v_{2},u_{1}\\rangle}{\\langle u_{1},u_{1}\\rangle}u_{1}', 'u_{2}=v_{2}-\\frac{\\langle v_{2},u_{1}\\rangle}{\\langle u_{1},u_{1}\\rangle}u_{1}', 'proof_step', 'final', 11),
(159, 6, 66, 262, 'M6.23', '3.221', 'Allgemeiner Gram-Schmidt-Schritt', 'u_{k}=v_{k}-\\sum_{j=1}^{k-1}\\frac{\\langle v_{k},u_{j}\\rangle}{\\langle u_{j},u_{j}\\rangle}u_{j}', 'u_{k}=v_{k}-\\sum_{j=1}^{k-1}\\frac{\\langle v_{k},u_{j}\\rangle}{\\langle u_{j},u_{j}\\rangle}u_{j}', 'proof_step', 'final', 11),
(160, 6, 66, 263, 'M6.24', '3.222', 'Normierung der Gram-Schmidt-Vektoren', 'q_{k}=\\frac{u_{k}}{\\lVert u_{k}\\rVert}', 'q_{k}=\\frac{u_{k}}{\\lVert u_{k}\\rVert}', 'proof_step', 'final', 11),
(161, 6, 66, 264, 'M6.25', '3.223', 'Erhaltung des Spannraums durch Gram-Schmidt', '\\operatorname{span}\\{v_{1},\\ldots,v_{m}\\}=\\operatorname{span}\\{q_{1},\\ldots,q_{m}\\}', '\\operatorname{span}\\{v_{1},\\ldots,v_{m}\\}=\\operatorname{span}\\{q_{1},\\ldots,q_{m}\\}', 'proof_step', 'final', 11),
(162, 6, 67, 265, 'M6.26', '3.224', 'Entwicklung eines Vektors in einer orthonormalen Basis', 'x=\\sum_{i=1}^{n}\\langle q_{i},x\\rangle q_{i}', 'x=\\sum_{i=1}^{n}\\langle q_{i},x\\rangle q_{i}', 'proof_step', 'final', 11),
(163, 6, 67, 266, 'M6.27', '3.225', 'Operatorwirkung in einer orthonormalen Eigenbasis', 'Ax=\\sum_{i=1}^{n}\\lambda_{i}\\langle q_{i},x\\rangle q_{i}', 'Ax=\\sum_{i=1}^{n}\\lambda_{i}\\langle q_{i},x\\rangle q_{i}', 'proof_step', 'final', 11),
(164, 6, 68, 267, 'M6.28', '3.226', 'Skalarprodukt des Beispielvektorenpaars', '\\langle x,y\\rangle=3(-4)+4(3)=0', '\\langle x,y\\rangle=3(-4)+4(3)=0', 'derived', 'final', 11),
(165, 6, 68, 268, 'M6.29', '3.227', 'Orthogonalität des Beispielvektorenpaars', 'x\\perp y', 'x\\perp y', 'derived', 'final', 11),
(166, 6, 68, 269, 'M6.30', '3.228', 'Norm des ersten Beispielvektors', '\\lVert x\\rVert=\\sqrt{3^{2}+4^{2}}=5', '\\lVert x\\rVert=\\sqrt{3^{2}+4^{2}}=5', 'derived', 'final', 11),
(167, 6, 68, 270, 'M6.31', '3.229', 'Norm des zweiten Beispielvektors', '\\lVert y\\rVert=\\sqrt{(-4)^{2}+3^{2}}=5', '\\lVert y\\rVert=\\sqrt{(-4)^{2}+3^{2}}=5', 'derived', 'final', 11),
(168, 6, 68, 271, 'M6.32', '3.230', 'Normierte Beispielvektoren', '\\widehat{x}=\\begin{pmatrix}\\frac{3}{5}\\\\\\frac{4}{5}\\end{pmatrix},\\quad\\widehat{y}=\\begin{pmatrix}-\\frac{4}{5}\\\\\\frac{3}{5}\\end{pmatrix}', '\\widehat{x}=\\begin{pmatrix}\\frac{3}{5}\\\\\\frac{4}{5}\\end{pmatrix},\\quad\\widehat{y}=\\begin{pmatrix}-\\frac{4}{5}\\\\\\frac{3}{5}\\end{pmatrix}', 'derived', 'final', 11),
(169, 6, 70, 274, 'M6.33', '3.233', 'Hierarchie geometrischer Zusatzstrukturen', '\\text{Vektorraum}\\longrightarrow\\text{Skalarproduktraum}\\longrightarrow\\text{Norm}\\longrightarrow\\text{Abstand und Winkel}', '\\text{Vektorraum}\\longrightarrow\\text{Skalarproduktraum}\\longrightarrow\\text{Norm}\\longrightarrow\\text{Abstand und Winkel}', 'derived', 'final', 11),
(170, 6, 71, 275, 'M6.34', '3.234', 'Didaktische Strukturkette von der Geometrie zur Zerlegung', '\\text{Skalarprodukt}\\longrightarrow\\text{Länge und Winkel}\\longrightarrow\\text{Orthogonalität}\\longrightarrow\\text{Projektion}\\longrightarrow\\text{orthonormale Zerlegung}', '\\text{Skalarprodukt}\\longrightarrow\\text{Länge und Winkel}\\longrightarrow\\text{Orthogonalität}\\longrightarrow\\text{Projektion}\\longrightarrow\\text{orthonormale Zerlegung}', 'derived', 'final', 11);
