(104, 1, 30, '3.105', '3.44', 1855, 'explicit', '\\det(A) = 0\\quad \\Longleftrightarrow \\quad A\\,\\text{ist singulär}\\quad \\Longleftrightarrow \\quad A^{- 1}\\,\\text{existiert nicht}', NULL, '\\det(\\mathbb A)=0\\quad\\Longleftrightarrow\\quad\\mathbb A\\ \\text{ist singulär}\\quad\\Longleftrightarrow\\quad\\mathbb A^{-1}\\ \\text{existiert nicht}', '\\det(\\mathbb A)=0\\quad\\Longleftrightarrow\\quad\\mathbb A\\ \\text{ist singulär}\\quad\\Longleftrightarrow\\quad\\mathbb A^{-1}\\ \\text{existiert nicht}', 'Singularität und verschwindende Determinante', 'canonical', 'literature', 'ok', 'accepted', 'Neuaufbau 3.2.4 / RKB32-REWRITE-3.2.4-2026-09-04: sichtbare Haupttextnummer (3.44); source_equation_number und source_latex bleiben unverändert.', 2),
(105, 1, 30, '3.106', 'M3.14', 1878, 'explicit', '\\det(A) = 1 \\cdot 4 - 2 \\cdot 2 = 0', NULL, '\\det(A)=1\\cdot4-2\\cdot2=0', '\\det(A)=1\\cdot4-2\\cdot2=0', NULL, 'needs_review', 'needs_review', 'ok', 'rewrite', 'Anlage M3: sichtbare Gleichungsnummer (M3.14); technischer Anker bleibt unverändert. | Anlage M3: sichtbare Gleichungsnummer (M3.14); technischer Anker bleibt unverändert.', 2),
(106, 1, 30, '3.107', '3.45', 1895, 'explicit', '\\det(A) \\neq 0\\quad \\Longleftrightarrow \\quad a_{1},\\ldots,a_{n}\\,\\text{sind linear unabhängig}\\quad \\Longleftrightarrow \\quad\\text{rank}(A) = n\\quad \\Longleftrightarrow \\quad A^{- 1}\\,\\text{existiert}', NULL, '\\det(\\mathbb A)\\neq0\\quad\\Longleftrightarrow\\quad\\mathbb a_1,\\ldots,\\mathbb a_n\\ \\text{sind linear unabhängig}\\quad\\Longleftrightarrow\\quad\\operatorname{rang}(\\mathbb A)=n\\quad\\Longleftrightarrow\\quad\\mathbb A^{-1}\\ \\text{existiert}', '\\det(\\mathbb A)\\neq0\\quad\\Longleftrightarrow\\quad\\mathbb a_1,\\ldots,\\mathbb a_n\\ \\text{sind linear unabhängig}\\quad\\Longleftrightarrow\\quad\\operatorname{rang}(\\mathbb A)=n\\quad\\Longleftrightarrow\\quad\\mathbb A^{-1}\\ \\text{existiert}', 'Nichtverschwindende Determinante, Unabhängigkeit, voller Rang und Invertierbarkeit', 'canonical', 'adapted', 'ok', 'accepted', 'Neuaufbau 3.2.4 / RKB32-REWRITE-3.2.4-2026-09-04: sichtbare Haupttextnummer (3.45); source_equation_number und source_latex bleiben unverändert.', 2),
