(228, 1, 34, '3.229', 'M6.31', 3653, 'explicit', '\\text{|}y\\text{|} = \\sqrt{( - 4)^{2} + 3^{2}} = 5', NULL, '\\lVert y\\rVert=\\sqrt{(-4)^{2}+3^{2}}=5', '\\lVert y\\rVert=\\sqrt{(-4)^{2}+3^{2}}=5', NULL, 'needs_review', 'needs_review', 'ok', 'rewrite', 'Anlage M6: sichtbare Gleichungsnummer (M6.31); technischer Anker bleibt unverändert; Quellintegrität laut Anlagenprofil ok. Redaktionelle Notationsnormalisierung ausschließlich in proposed_latex/word_latex; source_latex bleibt unverändert.', 2),
(229, 1, 34, '3.230', 'M6.32', 3657, 'explicit', '\\widehat{x} = \\begin{pmatrix}\n3\\text{/}5 \\\\\n4\\text{/}5\n\\end{pmatrix},\\quad\\quad\\widehat{y} = \\begin{pmatrix}\n - 4\\text{/}5 \\\\\n3\\text{/}5\n\\end{pmatrix}', NULL, '\\widehat{x}=\\begin{pmatrix}\\frac{3}{5}\\\\\\frac{4}{5}\\end{pmatrix},\\quad\\widehat{y}=\\begin{pmatrix}-\\frac{4}{5}\\\\\\frac{3}{5}\\end{pmatrix}', '\\widehat{x}=\\begin{pmatrix}\\frac{3}{5}\\\\\\frac{4}{5}\\end{pmatrix},\\quad\\widehat{y}=\\begin{pmatrix}-\\frac{4}{5}\\\\\\frac{3}{5}\\end{pmatrix}', NULL, 'needs_review', 'needs_review', 'ok', 'rewrite', 'Anlage M6: sichtbare Gleichungsnummer (M6.32); technischer Anker bleibt unverändert; Quellintegrität laut Anlagenprofil ok. Redaktionelle Notationsnormalisierung ausschließlich in proposed_latex/word_latex; source_latex bleibt unverändert.', 2),
(230, 1, 34, '3.231', '3.78', 3673, 'explicit', '\\left\\langle x,y \\right\\rangle_{G} = x^{T}Gy', NULL, '\\langle\\mathbb x,\\mathbb y\\rangle_{\\mathbb G}=\\mathbb x^{T}\\mathbb G\\mathbb y', '\\langle\\mathbb x,\\mathbb y\\rangle_{\\mathbb G}=\\mathbb x^{T}\\mathbb G\\mathbb y', 'Skalarprodukt mit positiver Metrikmatrix', 'canonical', 'adapted', 'ok', 'accepted', 'Neuaufbau 3.2.6 / RKB32-REWRITE-3.2.6-2026-09-04: sichtbare Haupttextnummer (3.78); source_equation_number und source_latex bleiben unverändert.', 2),
(231, 1, 34, '3.232', '3.79', 3685, 'explicit', '\\text{|}x\\text{|}_{G} = \\sqrt{x^{T}Gx}', NULL, '\\lVert\\mathbb x\\rVert_{\\mathbb G}=\\sqrt{\\mathbb x^{T}\\mathbb G\\mathbb x}', '\\lVert\\mathbb x\\rVert_{\\mathbb G}=\\sqrt{\\mathbb x^{T}\\mathbb G\\mathbb x}', 'Norm zur Metrikmatrix', 'canonical', 'adapted', 'ok', 'accepted', 'Neuaufbau 3.2.6 / RKB32-REWRITE-3.2.6-2026-09-04: sichtbare Haupttextnummer (3.79); source_equation_number und source_latex bleiben unverändert.', 2),
(232, 1, 34, '3.233', 'M6.33', 3703, 'explicit', '\\text{Vektorraum} \\longrightarrow \\text{Skalarproduktraum} \\longrightarrow \\text{Norm} \\longrightarrow \\text{Abstand und Winkel}', NULL, '\\text{Vektorraum}\\longrightarrow\\text{Skalarproduktraum}\\longrightarrow\\text{Norm}\\longrightarrow\\text{Abstand und Winkel}', '\\text{Vektorraum}\\longrightarrow\\text{Skalarproduktraum}\\longrightarrow\\text{Norm}\\longrightarrow\\text{Abstand und Winkel}', NULL, 'needs_review', 'needs_review', 'ok', 'rewrite', 'Anlage M6: sichtbare Gleichungsnummer (M6.33); technischer Anker bleibt unverändert; Quellintegrität laut Anlagenprofil ok.', 2),
