(234, 1, 23, 'RW321-3.6', '3.6', 203, 'source_context', '(a,b)=(c,d) \\Longleftrightarrow a=c \\land b=d', NULL, '(a,b)=(c,d)\\quad\\Longleftrightarrow\\quad a=c\\land b=d', '(a,b)=(c,d)\\quad\\Longleftrightarrow\\quad a=c\\land b=d', 'Gleichheitsbedingung geordneter Paare', 'derived', 'adapted', 'ok', 'accepted', 'Neuaufbau 3.2.1: revisionsgebundene Haupttext-Ableitung aus der in M1 behandelten Struktur geordneter Paare; M1.13 bleibt unverändert.', 17),
(235, 1, 23, 'RW321-3.7', '3.7', 209, 'source_context', 'A \\times B = \\{(a,b)\\mid a\\in A \\land b\\in B\\}', NULL, 'A\\times B=\\{(a,b)\\mid a\\in A,\\ b\\in B\\}', 'A\\times B=\\{(a,b)\\mid a\\in A,\\ b\\in B\\}', 'Kartesisches Produkt', 'derived', 'adapted', 'ok', 'accepted', 'Neuaufbau 3.2.1: Haupttext-Ableitung aus M1.14; das originale M1-Objekt bleibt appendix/final.', 17),
