INSERT INTO `repository_revisions` (`revision_id`, `revision_code`, `revision_date`, `scope_type`, `scope_reference`, `version_label`, `summary`, `created_by`, `parent_revision_id`) VALUES
(1, 'CH3.1-LIT-20260809', '2026-08-09 08:46:00', 'chapter', '3.1', '3.1-literaturbereinigt', 'Deduplizierte Literatur, korrigierte Erstnennungen, Source-Usage-Matrix und Abschnittsstruktur Kapitel 3.1. Gleichungen gemäß leerem equations-Bestand nicht erfunden.', 'Olaf Thiele / ChatGPT', NULL),
(2, 'RKB32-NEW-BASELINE-2026-08-29', '2026-08-29 15:17:00', 'chapter', '3.2', 'source-baseline-1', 'Quellimport der aktuellen Fassung von Kapitel 3.2 als Staging-Bestand. Die kanonischen Register des 3.1-Repositories bleiben führend; noch nicht redaktionell freigegebene Definitionen, Satzkandidaten und Gleichungen werden getrennt als Kandidaten geführt.', 'Olaf Thiele / ChatGPT', 1),
(3, 'RKB32-DEEP-RESEARCH-SOURCES-2026-08-29', '2026-08-29 16:00:00', 'chapter', '3.2', 'deep-research-sources-1', 'Deep-Research-Prüfung der Literaturverwendungen von Kapitel 3.2 mit abschnittsspezifischen Fundstellen, Belegparaphrasen, selektiven verifizierten Kurzzitaten und Auflösung der provisorischen Ziffern [10] und [13].', 'Olaf Thiele / ChatGPT', 2),
(4, 'RKB32-CONFORM-31-2026-08-29', '2026-08-29 16:50:00', 'repository', '3.1->3.2', '3.2-conform-3.1', 'Konformitätsmigration: Der Repository-Stand Ende 3.1 bleibt vollständige Basisschicht. Kapitel 3.2 ergänzt die bestehenden Register, ohne Tabellen, IDs, Quellen oder Auditstrukturen aus 3.1 zu verwerfen.', 'Olaf Thiele / ChatGPT', 3),
(5, 'RKB32-MATH-APPENDIX-PROFILE-2026-08-30', '2026-08-30 09:40:00', 'chapter', '3.2', 'math-appendix-profile-1', 'Einführung einer normalisierten Dokumentort-, Bedeutung- und Anforderungsstruktur für mathematische Objekte. Ziel: Kapitel 3.2 argumentativ straffen, ohne mathematische Inhalte zu verlieren; ausgelagerte Inhalte bleiben über Anlagenanker vollständig referenzierbar.', 'Olaf Thiele / ChatGPT', 4),
(6, 'RKB32-M1-APPENDIX-NUMBERED-2026-09-01', '2026-09-01 13:21:00', 'chapter', 'M1', 'm1-numbered-2', 'Neufassung Anlage M1: 26 sichtbare Gleichungsnummern M1.1–M1.26, vollständige Word-LaTeX-Synchronisierung, kanonisch nummerierte Literaturquellen [6], [72], [80], [83], Anlagen-Quellenregister und Gleichungs-Quellenverknüpfungen.', 'Olaf Thiele / ChatGPT', 5),
(7, 'RKB32-M2-APPENDIX-NUMBERED-CITATIONFMT-2026-09-02', '2026-09-02 16:39:00', 'chapter', 'M2', 'm2-numbered-citationfmt-3', 'Neufassung Anlage M2: 23 sichtbare Gleichungsnummern M2.1–M2.23, drei Definitionen, vollständige Word-LaTeX-Synchronisierung, kanonische Literaturquellen [71], [74], [82] und Zitierformat mit vollständiger Erstnennung sowie Kurzverweis bei Wiederholung; Anlagen-Quellenregister und Gleichungs-Quellenverknüpfungen.', 'Olaf Thiele / ChatGPT', 6),
(8, 'RKB32-M3-APPENDIX-NUMBERED-CITATIONFMT-2026-09-02', '2026-09-02 18:07:00', 'chapter', 'M3', 'm3-numbered-citationfmt-1', 'Anlage M3: 14 nummerierte Gleichungen M3.1–M3.14, Word-LaTeX, Objektplatzierungen, kanonische Quellen [71], [74], [82] und revisionsgesicherte Integritätskorrekturen.', 'Olaf Thiele / ChatGPT', 7),
(9, 'RKB32-M4-APPENDIX-NUMBERED-CITATIONFMT-2026-09-02', '2026-09-02 18:07:00', 'chapter', 'M4', 'm4-numbered-citationfmt-1', 'Anlage M4: sechs nummerierte Gleichungen M4.1–M4.6, vollständige Abschnittstexte, Word-LaTeX, Objektplatzierungen und kanonische Quellen [71], [74], [82].', 'Olaf Thiele / ChatGPT', 8),
(10, 'RKB32-M5-APPENDIX-NUMBERED-CITATIONFMT-2026-09-02', '2026-09-02 18:30:00', 'chapter', 'M5', 'm5-numbered-citationfmt-1', 'Anlage M5: 30 nummerierte Gleichungen M5.1–M5.30, vollständige Abschnittstexte, Word-LaTeX, Objektplatzierungen, Quellen [71], [74], [76], [82] und dokumentierte Quellintegritätskorrektur M5-GL-172.', 'Olaf Thiele / ChatGPT', 9),
(11, 'RKB32-M6-APPENDIX-NUMBERED-CITATIONFMT-2026-09-02', '2026-09-02 19:30:00', 'chapter', 'M6', 'm6-numbered-citationfmt-1', 'Anlage M6: 42 Anlagenobjekte, davon 34 nummerierte Gleichungen M6.1–M6.34, vier Definitionen, vier Satz-/Verfahrensobjekte, vollständige Abschnittstexte, Word-LaTeX, Objektplatzierungen und Quellen [74], [75], [76], [84].', 'Olaf Thiele / ChatGPT', 10),
(14, 'RKB32-MATH-APPENDICES-M1-M6-FINAL-GATE-2026-09-02', '2026-09-02 19:20:00', 'chapter', '3.2 / M1-M6', 'math-appendices-final-gate-1', 'Abschlussrevision der mathematischen Anlagen M1-M6: M1-Zitationsformat synchronisiert; 144 Anlagenobjekte, 133 Anlagengleichungen, Word-LaTeX, Literaturverknuepfungen, technische Anker, Quellintegritaet und globale Compression-Gates werden geprueft. Finalisierung erfolgt nur bei vollstaendig bestandenem Gate.', 'Olaf Thiele / ChatGPT', 11),
(16, 'RKB32-REWRITE-3.2.0-2026-09-02', '2026-09-04 04:00:00', 'section', '3.2.0', '3.2.0-neufassung-2-rollback-rebuild', 'Rollback und Neuaufbau von 3.2.0. Die ueberholte Rewrite-Fassung wird zuerst auf den Dump-Basisstand zurueckgestellt. Anschliessend wird 3.2.0 ohne Rueckverweise auf vorangegangene Kapitel, mit explizit benannten Uebergabestellen zu M1-M6 und zu 3.2.1 neu gespeichert. Der Revisionsanker bleibt fuer die bereits darauf aufbauende 3.2.1-Revision stabil.', 'Olaf Thiele / ChatGPT', 14),
(17, 'RKB32-REWRITE-3.2.1-2026-09-02', '2026-09-04 04:20:00', 'section', '3.2.1', '3.2.1-neufassung-2-rollback-rebuild', 'Rollback und Neuaufbau von 3.2.1. Die ueberholte Fassung mit 14 Gleichungen wird auf den Dump-Basisstand zurueckgestellt und anschliessend als aktuelle Fassung mit 3 Definitionen, 20 sichtbaren Gleichungen und explizit benannten Uebergabestellen neu aufgebaut. M1 bleibt final und unveraendert.', 'Olaf Thiele / ChatGPT', 16),
(18, 'RKB32-REWRITE-3.2.2-2026-09-02', '2026-09-04 04:45:00', 'section', '3.2.2', '3.2.2-neufassung-2', 'Rollback und Neuaufbau von 3.2.2. Die ueberholte Rewrite-Fassung wird gezielt auf den Dump-Basisstand zurueckgestellt und anschliessend als aktuelle Fassung mit sechs Definitionen, elf sichtbaren Gleichungen (3.21)-(3.31) und explizit benannten Uebergabestellen neu aufgebaut. Anlage M2 bleibt final und unveraendert.', 'Olaf Thiele / ChatGPT', 17),
(20, 'RKB32-REWRITE-3.2.3-2026-09-02', '2026-09-04 10:35:00', 'section', '3.2.3', '3.2.3-neufassung-2', 'Rollback und Neuaufbau von 3.2.3. Die überholte Rewrite-Fassung wird gezielt auf den Quell-/Dumpzustand zurückgestellt und anschließend mit zwei Definitionen, elf sichtbaren Gleichungen (3.32)-(3.42) und explizit benannten Übergabestellen neu aufgebaut. Anlage M3 bleibt final und unverändert; source_* Provenienz bleibt erhalten.', 'Olaf Thiele / ChatGPT', 18),
(26, 'RKB32-REWRITE-3.2.4-2026-09-04', '2026-09-04 10:55:00', 'section', '3.2.4', '3.2.4-neufassung-1', 'Neuaufbau von 3.2.4 Struktur linearer Operatoren: vier Definitionen, zwei kanonische Satz-/Kriteriumsobjekte und elf sichtbare Gleichungen (3.43)-(3.53). Übergabestellen zu M3, M4 und 3.2.5 werden explizit gespeichert. M3/M4 bleiben final und unverändert.', 'Olaf Thiele / ChatGPT', 20),
(27, 'RKB32-REWRITE-3.2.5-2026-09-04', '2026-09-04 11:30:00', 'section', '3.2.5', '3.2.5-neufassung-1', 'Neuaufbau 3.2.5 Eigenstruktur und Spektraldarstellung: sechs Definitionen, drei kanonische Satz-/Kriteriumsobjekte und zwölf sichtbare Gleichungen (3.54)-(3.65). M5 bleibt final mit 30 ausgelagerten Gleichungen; neue zusammengeführte Haupttextformeln werden transparent als adapted registriert.', 'Olaf Thiele / ChatGPT', 26),
(28, 'RKB32-REWRITE-3.2.6-2026-09-04', '2026-09-04 12:05:00', 'section', '3.2.6', '3.2.6-neufassung-1', 'Neuaufbau 3.2.6: Skalarprodukt, Norm, Orthogonalität, orthonormale Systeme, Projektion, metrisch gewichtetes Skalarprodukt und Hilbertraumanschluss. Sechs Definitionen und fünfzehn sichtbare Gleichungen (3.66)-(3.80). M6 bleibt final mit 42 Objekten und 34 Gleichungen.', 'Olaf Thiele / ChatGPT', 27),
(29, 'RKB32-REWRITE-3.2.7-2026-09-04', '2026-09-04 12:55:00', 'section', '3.2.7', '3.2.7-neufassung-1', 'Neuaufbau 3.2.7 als reine Syntheseebene ohne neue mathematische Primärobjekte oder FRZK-Axiome; explizite Übergabe zu M1-M6 und 3.3; Kapitelabschluss-Audit ohne vorgetäuschte Live-Ausführung oder Enddump-Freigabe.', 'Olaf Thiele / ChatGPT', 28),
(30, 'RKB32-FINAL-GATE-3.2-TO-3.3-2026-09-04', '2026-09-04 13:05:00', 'chapter', '3.2', '3.2-final-gate-1', 'Technischer Abschluss Kapitel 3.2: Wiederherstellung der Quellprovenienz, Einführung der kanonischen Haupttext-Platzierungs- und Section-Lineage-Schicht, Prüfung von 27 Definitionen, 80 sichtbaren Gleichungen, 5 Satz-/Kriteriumsobjekten, M1-M6, Literatur- und Compression-Gates. Finalisierung erfolgt ausschließlich bei vollständigem PASS.', 'Olaf Thiele / ChatGPT', 29),
(31, 'RKB32-FINAL-GATE-3.2-TO-3.3-2026-09-04-V2', '2026-09-04 16:55:00', 'chapter', '3.2', '3.2-final-gate-v2', 'Korrigiertes Übergangsgate 3.2->3.3 auf Basis des realen Dumps vom 2026-09-04 16:47: Legacy-Compression-Profil 48 normalisieren, fehlende Requirements 276-282 ergänzen, Critical-Issues 1/2/4 evidenzbasiert schließen und Kapitel ausschließlich bei vollständigem PASS finalisieren.', 'Olaf Thiele / ChatGPT', 30);
