INSERT INTO `revision_issues` (`issue_id`, `severity`, `issue_category`, `object_reference`, `description`, `required_action`, `issue_status`, `created_revision_id`) VALUES
(0, 'info', 'appendix_release_gate', 'Kapitel 3.2 / Anlagen M1-M6', 'Gemeinsames Abschluss-Gate M1-M6; fehlgeschlagene Gates: 0.', 'Keine weitere Anlagenkorrektur erforderlich; Haupttext 3.2 kann auf Basis der finalisierten Anlagen neu montiert werden.', 'resolved', 14),
(1, 'critical', 'equation', '3.2.3 / (3.49)', 'Die Formel Ax=y ist vorhanden, die sichtbare Gleichungsnummer (3.49) fehlt in der Quellfassung.', 'Bei der Neufassung Gleichung eindeutig setzen und Word-LaTeX unmittelbar nachführen. | Erledigt durch Neufassung: source 3.49 ist als sichtbare Haupttextgleichung (3.38) revisionsgesichert, mit Word-LaTeX und akzeptierter Haupttextplatzierung.', 'resolved', 2),
(2, 'critical', 'equation', '3.2.3 / (3.50)', 'Die Eigenwertgleichung ist vorhanden, die sichtbare Gleichungsnummer (3.50) fehlt; die Zuordnung ergibt sich nur aus dem Abschnittskontext.', 'Bei der Neufassung formal neu setzen und Nummer explizit bestätigen. | Erledigt durch Anlage M3: source 3.50 ist als finale Gleichung M3.5 mit vollständigem LaTeX und Word-LaTeX registriert.', 'resolved', 2),
(3, 'critical', 'equation', '3.2.6 / (3.73)', 'Zwischen (3.72) und (3.74) fehlt in der Quellfassung eine Gleichungsnummer vollständig; es wird keine Formel für (3.73) erfunden.', 'Im Rewrite entscheiden, ob neu nummeriert oder die Lücke dokumentiert geschlossen wird. | Erledigt durch RKB32-REWRITE-3.2.2-2026-09-02: Die aktuelle Haupttextzählung läuft lückenlos von (3.21) bis (3.31). Für die im Quellbestand fehlende Nummer (3.73) wurde keine Formel erfunden; die Quellnummern bleiben ausschließlich als Provenienz erhalten.', 'resolved', 2),
(4, 'critical', 'equation', '3.2.11 / (3.173)', 'Die Projektorgleichung ist beschädigt; der Ausdruck endet in der Quellfassung bei lambda != und die rechte Vergleichsgröße fehlt.', 'Mathematisch gegen den Kontext und Literatur prüfen und im Rewrite korrigieren. | Erledigt durch Anlage M5: der beschädigte Quellpayload 3.173 bleibt provenance-seitig erhalten; die mathematisch vollständige Fassung ist final als M5.25 mit Word-LaTeX registriert.', 'resolved', 2),
(5, 'high', 'word_latex', 'Kapitel 3.2', 'Im gesamten DOCX ist nur ein expliziter Word-LaTeX-Absatz vorhanden, obwohl der Formelbestand 233 tatsächlich vorhandene nummerierte Gleichungen umfasst.', 'Bei jeder neu gesetzten Gleichung Word-LaTeX verpflichtend synchron pflegen. | Erledigt im Neuaufbau: sämtliche 80 akzeptiert platzierten sichtbaren Haupttextgleichungen besitzen Word-LaTeX.', 'resolved', 2),
(6, 'high', 'citation', '3.2.3 ff. / [10]', 'Die Literaturzahl [10] wird in der Quellfassung wiederholt für lineare Algebra verwendet, ist aber im aktuellen Literaturblock nicht aufgelöst.', 'Nicht übernehmen; Quelle vor Neufassung bibliografisch identifizieren oder durch passende verifizierte Quelle ersetzen. | Erledigt im Neuaufbau: die betreffende alte Literaturzahl wird in keiner source_usage der Zielabschnitte 3.2.0-3.2.7 verwendet.', 'resolved', 2),
(7, 'high', 'citation', '3.2.3 ff. / [13]', 'Die Literaturzahl [13] wird wiederholt bei Operatoren/Funktionalanalysis verwendet, ist im aktuellen Literaturblock nicht aufgelöst.', 'Nicht übernehmen; Quelle vor Neufassung bibliografisch identifizieren oder durch passende verifizierte Quelle ersetzen. | Erledigt im Neuaufbau: die betreffende alte Literaturzahl wird in keiner source_usage der Zielabschnitte 3.2.0-3.2.7 verwendet.', 'resolved', 2),
(8, 'high', 'scope', '3.2.0 vs. Kapitelbestand', 'Die Einleitung kündigt Analysis, Topologie, Funktionalanalysis, Graphentheorie, Kategorientheorie und Metamathematik an; die vorliegende Datei endet nach 3.2.12 und kündigt 3.2.13 lediglich an.', 'Kapitelstruktur vor der Endfassung vollständig festlegen und angekündigte Gebiete entweder ausarbeiten oder den Scope der Einleitung anpassen. | Erledigt durch RKB32-REWRITE-3.2.0-2026-09-02 / Neuaufbau 2026-09-04: Die Einleitung beschränkt sich auf den tatsächlich vorgesehenen mathematischen Hauptpfad 3.2.0-3.2.7.', 'resolved', 2),
(9, 'high', 'editorial_artifact', '3.2.7', 'Im Dissertationstext steht ein Chat-/Arbeitsrest: „Du meinst im unmittelbaren Fortgang 3.2.7 …“.', 'Vollständig aus dem wissenschaftlichen Fließtext entfernen. | Erledigt durch vollständigen wissenschaftlichen Neusatz 3.2.0-3.2.7.', 'resolved', 2),
(10, 'medium', 'editorial_artifact', '3.2.7–3.2.12', 'Mehrere Abschnitte enthalten Arbeitsvermerke „Fortsetzungsstand: …“.', 'Aus Dissertationstext entfernen; Fortsetzungsstand ausschließlich im Repository führen. | Erledigt durch vollständigen wissenschaftlichen Neusatz 3.2.0-3.2.7.', 'resolved', 2),
(11, 'medium', 'editorial_artifact', '3.2.1 / 3.2.12', 'Repository- und Skriptanweisungen stehen im Dissertationstext, u. a. zur späteren Prüfung von Frege/Tarski und source_excerpt.', 'In Repository-Metadaten verschieben; im Fließtext nur wissenschaftliche Aussage belassen. | Erledigt durch RKB32-REWRITE-3.2.1-2026-09-02 / Neuaufbau 2026-09-04: interne Repository-/Skriptanweisungen sind nicht Bestandteil des Dissertationstextes.', 'resolved', 2),
(12, 'medium', 'formatting', '3.2.12', 'Mindestens eine Formel (Skalarprodukt) ist im DOCX als Überschrift formatiert.', 'Formatierung im Neusatz normalisieren; Formeln niemals als Kapitelüberschrift führen. | Erledigt durch den vollständigen Neusatz 3.2.6; die alte 3.2.12-DOCX-Überschriftenformatierung ist nicht Bestandteil der Rewrite-Fassung.', 'resolved', 2),
(13, 'medium', 'definition_overlap', 'Definition 3.2.3 / 3.2.4', '„Funktion“ und „Mathematische Abbildung“ sind in der Quellfassung weitgehend doppelt definiert.', 'Im Rewrite terminologisch konsolidieren oder den unterschiedlichen Gebrauch ausdrücklich begründen. | Erledigt in 3.2.1: Funktion ist kanonisch als Definition 3.2.3 geführt; eine redundante neue Haupttextdefinition „Mathematische Abbildung“ wurde nicht übernommen.', 'resolved', 2),
(14, 'medium', 'citation_style', '3.2.0', 'Die Einleitung enthält lange bibliografische Vollangaben im Fließtext statt einer knappen wissenschaftlichen Quellenführung.', 'Vollangaben in Literaturregister/DB führen und im Kapitel nur die für die Argumentation nötige Quellenangabe verwenden. | Erledigt durch RKB32-REWRITE-3.2.0-2026-09-02 / Neuaufbau 2026-09-04: 3.2.0 enthält keine bibliografischen Vollangaben im Fließtext.', 'resolved', 2),
(15, 'medium', 'requirement_granularity', 'chapter:3.2->3.3', 'Die Haupttextobjekte sind derzeit nachweisbar auf Kapitel 3.3 als Zielbereich gemappt; eine belastbare 3.3.x-Feinzuordnung ist in diesem Repository-Stand noch nicht vorhanden.', 'Nach Import bzw. Festlegung der verbindlichen Kapitel-3.3-Struktur jede 3.3-Anforderung auf die konkrete Zieluntersektion 3.3.x auflösen und required_for_section_id setzen. | Für Gate 3.2->3.3 akzeptiert: Kapitelanforderungen sind vorhanden; Feinziel 3.3.x wird während der 3.3-Integration verbindlich aufgelöst.', 'accepted', 5),
(16, 'medium', 'equation_source_integrity', 'M1-GL-039 / source equation (3.39)', 'Der importierte Quellpayload endet unvollständig bei forall	heta in. Der zugehörige Text benennt Theta als Parametermenge.', 'source_latex unverändert bewahren; nur proposed_latex/word_latex als M1.25 vollständig mit Theta führen.', 'resolved', 6),
(17, 'medium', 'source_integrity', 'M2-GL-057 / equation_candidates#57', 'Der importierte Quellpayload verwendet 0_{R^{\\mathbb{2}}} statt einer gültigen Schreibweise für den Nullvektor in R^2.', 'Quellpayload unverändert bewahren; redaktionelle proposed-/Word-LaTeX-Fassung als 0_{\\mathbb{R}^{2}} führen.', 'resolved', 7),
(18, 'medium', 'source_integrity', 'M2-GL-075 / equation_candidates#75', 'Die importierte Summationsbedingung enthält die beschädigte Zeichenfolge 1\\backslash\\backslash i \\neq j.', 'Quellpayload unverändert bewahren; redaktionelle Fassung mit \\substack{i=1\\\\i\\neq j} führen.', 'resolved', 7),
(19, 'medium', 'source_integrity', 'M2-GL-076 / equation_candidates#76', 'Das Beispiel verwendet erneut die beschädigte Nullvektor-Schreibweise 0_{R^{\\mathbb{2}}}.', 'Quellpayload unverändert bewahren; redaktionelle Fassung mit 0_{\\mathbb{R}^{2}} führen.', 'resolved', 7),
(20, 'medium', 'source_integrity', 'M3-GL-044 / equation_candidates#44', 'Der importierte Quellpayload zur Operatorverkettung wiederholt die Signatur von A, lässt B aus und enthält x=B(A(x)) statt der Wirkung der Komposition.', 'Quellpayload unverändert bewahren; redaktionelle Formel als A,B:V→V und (B∘A)(x)=B(A(x)) führen.', 'resolved', 8),
(21, 'medium', 'source_integrity', 'M3-GL-099 / equation_candidates#99', 'Die importierte Laplace-Entwicklung enthält die beschädigten Indizes a_{2311} und a_{1121}.', 'Quellpayload unverändert bewahren; redaktionell die Minoren mit a_{23} bzw. a_{21} korrekt führen.', 'resolved', 8),
(22, 'medium', 'source_integrity', 'M3-GL-102 / equation_candidates#102', 'Die importierte Orientierungsfallunterscheidung enthält ein zusätzliches Anführungszeichen und eine fehlerhafte geschweifte Klammer.', 'Quellpayload unverändert bewahren; redaktionelle Fallunterscheidung syntaktisch korrekt führen.', 'resolved', 8),
(23, 'low', 'source_integrity', 'M3-GL-050 / equation_candidates#50', 'Die Eigenwertgleichung ist im Quellpayload ohne zuverlässig erhaltene sichtbare Gleichungsnummer importiert; source_integrity_status=number_missing.', 'Quellintegrität number_missing bewahren; M3.5 als eindeutige sichtbare Anlagen-Gleichungsnummer führen und die Zuordnung zu 3.50 nur als Provenienz behandeln.', 'resolved', 8),
(24, 'medium', 'source_integrity', 'M5-GL-172 / equation_candidates#172', 'Der importierte Quellpayload der Projektororthogonalität endet unvollständig nach P_{lambda}P_{mu}=0 für lambda != und enthält den zweiten Vergleichsindex nicht.', 'Quellpayload unverändert bewahren; redaktionelle proposed_latex-/Word-LaTeX-Fassung als P_{lambda}P_{mu}=0 für lambda != mu führen.', 'resolved', 10);
